+package s2
+
+import (
+	"fmt"
+	"io"
+	"math"
+	"slices"
+	"sync/atomic"
+)
+
+// The ShapeIndex encoding format (all integers are uvarints unless noted):
+//
+//	version            uint8
+//	maxEdgesPerCell
+//	nextID
+//	numShapes
+//	numShapes x {
+//	    shapeID
+//	    shapeType      uint8
+//	    shape payload  (see encodeIndexShape)
+//	}
+//	numCells
+//	numCells x {
+//	    cellID         uint64 (little endian)
+//	    numClipped
+//	    numClipped x {
+//	        shapeID
+//	        containsCenter  bool
+//	        numEdges
+//	        numEdges x edgeID
+//	    }
+//	}
+//
+// Points are encoded as three little endian float64s and Rects as four
+// little endian float64s (Lat.Lo, Lat.Hi, Lng.Lo, Lng.Hi).
+
+const shapeIndexEncodingVersion = uint8(1)
+
+// Type tags for the built-in Shape types that can be stored in an encoded ShapeIndex.
+const (
+	shapeTypePointVector uint8 = iota + 1
+	shapeTypePolyline
+	shapeTypeLoop
+	shapeTypePolygon
+	shapeTypeLaxPolyline
+	shapeTypeLaxLoop
+	shapeTypeLaxPolygon
+)
+
+// decodeAllocChunk bounds the number of elements preallocated from a count
+// read from the input. Slices grow beyond this only as data is actually read,
+// so a malformed count cannot trigger a huge allocation.
+const decodeAllocChunk = 1024
+
+// Encode encodes the ShapeIndex, including its shapes and the full spatial
+// cell structure, so that it can be restored with Decode without rebuilding.
+// Any pending updates are applied before encoding.
+//
+// Only the built-in Shape types (PointVector, Polyline, Loop, Polygon,
+// LaxPolyline, LaxLoop, and LaxPolygon) are supported; an error is returned
+// if the index contains any other type of Shape.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	s.maybeApplyUpdates()
+
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+
+	e := &encoder{w: w}
+	s.encode(e)
+	return e.err
+}
+
+func (s *ShapeIndex) encode(e *encoder) {
+	ids := make([]int32, 0, len(s.shapes))
+	for id := range s.shapes {
+		ids = append(ids, id)
+	}
+	slices.Sort(ids)
+
+	e.writeUint8(shapeIndexEncodingVersion)
+	e.writeUvarint(uint64(s.maxEdgesPerCell))
+	e.writeUvarint(uint64(s.nextID))
+	e.writeUvarint(uint64(len(ids)))
+	for _, id := range ids {
+		e.writeUvarint(uint64(id))
+		encodeIndexShape(e, s.shapes[id])
+		if e.err != nil {
+			return
+		}
+	}
+
+	// The cellMap is the authoritative set of cells; encode them in CellID order.
+	cellIDs := make([]CellID, 0, len(s.cellMap))
+	for id, cell := range s.cellMap {
+		if cell != nil {
+			cellIDs = append(cellIDs, id)
+		}
+	}
+	slices.Sort(cellIDs)
+
+	e.writeUvarint(uint64(len(cellIDs)))
+	for _, id := range cellIDs {
+		cell := s.cellMap[id]
+		e.writeUint64(uint64(id))
+		e.writeUvarint(uint64(len(cell.shapes)))
+		for _, c := range cell.shapes {
+			e.writeUvarint(uint64(c.shapeID))
+			e.writeBool(c.containsCenter)
+			e.writeUvarint(uint64(len(c.edges)))
+			for _, edge := range c.edges {
+				e.writeUvarint(uint64(edge))
+			}
+		}
+		if e.err != nil {
+			return
+		}
+	}
+}
+
+func encodeIndexShape(e *encoder, shape Shape) {
+	switch sh := shape.(type) {
+	case *PointVector:
+		e.writeUint8(shapeTypePointVector)
+		encodeIndexPoints(e, *sh)
+	case *Polyline:
+		e.writeUint8(shapeTypePolyline)
+		encodeIndexPoints(e, *sh)
+	case *Loop:
+		e.writeUint8(shapeTypeLoop)
+		encodeIndexLoop(e, sh)
+	case *Polygon:
+		e.writeUint8(shapeTypePolygon)
+		e.writeBool(sh.hasHoles)
+		e.writeUvarint(uint64(len(sh.loops)))
+		for _, l := range sh.loops {
+			encodeIndexLoop(e, l)
+		}
+		encodeIndexRect(e, sh.bound)
+	case *LaxPolyline:
+		e.writeUint8(shapeTypeLaxPolyline)
+		encodeIndexPoints(e, sh.vertices)
+	case *LaxLoop:
+		e.writeUint8(shapeTypeLaxLoop)
+		encodeIndexPoints(e, sh.vertices[:sh.numVertices])
+	case *LaxPolygon:
+		e.writeUint8(shapeTypeLaxPolygon)
+		e.writeUvarint(uint64(sh.numLoops))
+		for i := 0; i < sh.numLoops; i++ {
+			n := sh.numLoopVertices(i)
+			e.writeUvarint(uint64(n))
+			for j := 0; j < n; j++ {
+				encodeIndexPoint(e, sh.loopVertex(i, j))
+			}
+		}
+	default:
+		if e.err == nil {
+			e.err = fmt.Errorf("s2: cannot encode ShapeIndex containing unsupported shape type %T", shape)
+		}
+	}
+}
+
+func encodeIndexPoint(e *encoder, p Point) {
+	e.writeFloat64(p.X)
+	e.writeFloat64(p.Y)
+	e.writeFloat64(p.Z)
+}
+
+func encodeIndexPoints(e *encoder, pts []Point) {
+	e.writeUvarint(uint64(len(pts)))
+	for _, p := range pts {
+		encodeIndexPoint(e, p)
+	}
+}
+
+func encodeIndexRect(e *encoder, r Rect) {
+	e.writeFloat64(r.Lat.Lo)
+	e.writeFloat64(r.Lat.Hi)
+	e.writeFloat64(r.Lng.Lo)
+	e.writeFloat64(r.Lng.Hi)
+}
+
+func encodeIndexLoop(e *encoder, l *Loop) {
+	encodeIndexPoints(e, l.vertices)
+	e.writeBool(l.originInside)
+	e.writeUvarint(uint64(l.depth))
+	encodeIndexRect(e, l.bound)
+}
+
+// Decode decodes a ShapeIndex previously written by Encode, replacing the
+// current contents of s. The decoded index is fresh: queries and iteration
+// work immediately without calling Build, and shape IDs are preserved.
+//
+// If an error is returned, s is left unmodified.
+func (s *ShapeIndex) Decode(r io.Reader) (err error) {
+	defer func() {
+		// Validation below should reject all malformed input, but guard
+		// against any panics in shape construction as a last resort.
+		if p := recover(); p != nil {
+			err = fmt.Errorf("s2: malformed ShapeIndex encoding: %v", p)
+		}
+	}()
+
+	d := &decoder{r: asByteReader(r)}
+	tmp := decodeShapeIndex(d)
+	if d.err != nil {
+		if d.err == io.EOF {
+			d.err = io.ErrUnexpectedEOF
+		}
+		return fmt.Errorf("s2: decoding ShapeIndex: %w", d.err)
+	}
+
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.shapes = tmp.shapes
+	s.maxEdgesPerCell = tmp.maxEdgesPerCell
+	s.nextID = tmp.nextID
+	s.cellMap = tmp.cellMap
+	s.cells = tmp.cells
+	s.pendingAdditionsPos = int32(len(tmp.shapes))
+	s.pendingRemovals = nil
+	atomic.StoreInt32(&s.status, fresh)
+	return nil
+}
+
+// decodedShapeIndex holds the results of decoding before they are committed
+// to the destination ShapeIndex.
+type decodedShapeIndex struct {
+	shapes          map[int32]Shape
+	maxEdgesPerCell int
+	nextID          int32
+	cellMap         map[CellID]*ShapeIndexCell
+	cells           []CellID
+}
+
+// setDecodeErr records err if no earlier error has been recorded.
+func setDecodeErr(d *decoder, format string, args ...any) {
+	if d.err == nil {
+		d.err = fmt.Errorf(format, args...)
+	}
+}
+
+// readCount reads a uvarint count and verifies it does not exceed limit.
+func readCount(d *decoder, limit uint64, what string) int {
+	n := d.readUvarint()
+	if d.err != nil {
+		return 0
+	}
+	if n > limit {
+		setDecodeErr(d, "%s %d exceeds limit %d", what, n, limit)
+		return 0
+	}
+	return int(n)
+}
+
+func decodeShapeIndex(d *decoder) *decodedShapeIndex {
+	if v := d.readUint8(); d.err == nil && v != shapeIndexEncodingVersion {
+		setDecodeErr(d, "unsupported ShapeIndex encoding version %d", v)
+	}
+	maxEdges := readCount(d, math.MaxInt32, "max edges per cell")
+	nextID := readCount(d, math.MaxInt32, "next shape ID")
+	numShapes := readCount(d, uint64(nextID), "number of shapes")
+	if d.err != nil {
+		return nil
+	}
+
+	out := &decodedShapeIndex{
+		shapes:          make(map[int32]Shape, min(numShapes, decodeAllocChunk)),
+		maxEdgesPerCell: maxEdges,
+		nextID:          int32(nextID),
+		cellMap:         make(map[CellID]*ShapeIndexCell),
+	}
+
+	prevID := -1
+	for range numShapes {
+		id := readCount(d, uint64(nextID-1), "shape ID")
+		if d.err != nil {
+			return nil
+		}
+		if id <= prevID {
+			setDecodeErr(d, "shape IDs out of order: %d after %d", id, prevID)
+			return nil
+		}
+		prevID = id
+		shape := decodeIndexShape(d)
+		if d.err != nil {
+			return nil
+		}
+		out.shapes[int32(id)] = shape
+	}
+
+	numCells := readCount(d, math.MaxInt32, "number of cells")
+	if d.err != nil {
+		return nil
+	}
+	out.cells = make([]CellID, 0, min(numCells, decodeAllocChunk))
+	for range numCells {
+		id := CellID(d.readUint64())
+		if d.err != nil {
+			return nil
+		}
+		if !id.IsValid() {
+			setDecodeErr(d, "invalid cell ID %v", uint64(id))
+			return nil
+		}
+		if n := len(out.cells); n > 0 && id.RangeMin() <= out.cells[n-1].RangeMax() {
+			setDecodeErr(d, "cell %v is out of order or overlaps cell %v", id, out.cells[n-1])
+			return nil
+		}
+		cell := decodeIndexCell(d, out.shapes)
+		if d.err != nil {
+			return nil
+		}
+		out.cellMap[id] = cell
+		out.cells = append(out.cells, id)
+	}
+	return out
+}
+
+func decodeIndexCell(d *decoder, shapes map[int32]Shape) *ShapeIndexCell {
+	numClipped := readCount(d, uint64(len(shapes)), "number of shapes in cell")
+	if d.err != nil {
+		return nil
+	}
+	cell := &ShapeIndexCell{shapes: make([]*clippedShape, 0, min(numClipped, decodeAllocChunk))}
+	for range numClipped {
+		id := readCount(d, math.MaxInt32, "shape ID")
+		if d.err != nil {
+			return nil
+		}
+		shape, ok := shapes[int32(id)]
+		if !ok {
+			setDecodeErr(d, "cell references unknown shape ID %d", id)
+			return nil
+		}
+		if cell.findByShapeID(int32(id)) != nil {
+			setDecodeErr(d, "cell references shape ID %d more than once", id)
+			return nil
+		}
+		c := &clippedShape{shapeID: int32(id)}
+		c.containsCenter = d.readBool()
+		numShapeEdges := shape.NumEdges()
+		numEdges := readCount(d, uint64(numShapeEdges), "number of clipped edges")
+		if d.err != nil {
+			return nil
+		}
+		c.edges = make([]int, 0, min(numEdges, decodeAllocChunk))
+		for range numEdges {
+			edge := readCount(d, uint64(numShapeEdges-1), "edge ID")
+			if d.err != nil {
+				return nil
+			}
+			c.edges = append(c.edges, edge)
+		}
+		cell.shapes = append(cell.shapes, c)
+	}
+	return cell
+}
+
+func decodeIndexShape(d *decoder) Shape {
+	typ := d.readUint8()
+	if d.err != nil {
+		return nil
+	}
+	switch typ {
+	case shapeTypePointVector:
+		pts := PointVector(decodeIndexPoints(d))
+		return &pts
+	case shapeTypePolyline:
+		pts := Polyline(decodeIndexPoints(d))
+		return &pts
+	case shapeTypeLoop:
+		return decodeIndexLoop(d)
+	case shapeTypePolygon:
+		return decodeIndexPolygon(d)
+	case shapeTypeLaxPolyline:
+		return &LaxPolyline{vertices: decodeIndexPoints(d)}
+	case shapeTypeLaxLoop:
+		pts := decodeIndexPoints(d)
+		return &LaxLoop{numVertices: len(pts), vertices: pts}
+	case shapeTypeLaxPolygon:
+		numLoops := readCount(d, maxEncodedLoops, "number of loops")
+		loops := make([][]Point, 0, min(numLoops, decodeAllocChunk))
+		total := 0
+		for range numLoops {
+			pts := decodeIndexPoints(d)
+			if d.err != nil {
+				return nil
+			}
+			if total += len(pts); total > maxEncodedVertices {
+				setDecodeErr(d, "too many vertices (%d; max is %d)", total, maxEncodedVertices)
+				return nil
+			}
+			loops = append(loops, pts)
+		}
+		if d.err != nil {
+			return nil
+		}
+		return LaxPolygonFromPoints(loops)
+	default:
+		setDecodeErr(d, "unknown shape type %d", typ)
+		return nil
+	}
+}
+
+func decodeIndexPoint(d *decoder) Point {
+	var p Point
+	p.X = d.readFloat64()
+	p.Y = d.readFloat64()
+	p.Z = d.readFloat64()
+	return p
+}
+
+func decodeIndexPoints(d *decoder) []Point {
+	n := readCount(d, maxEncodedVertices, "number of vertices")
+	if d.err != nil {
+		return nil
+	}
+	pts := make([]Point, 0, min(n, decodeAllocChunk))
+	for range n {
+		p := decodeIndexPoint(d)
+		if d.err != nil {
+			return nil
+		}
+		pts = append(pts, p)
+	}
+	return pts
+}
+
+func decodeIndexRect(d *decoder) Rect {
+	var r Rect
+	r.Lat.Lo = d.readFloat64()
+	r.Lat.Hi = d.readFloat64()
+	r.Lng.Lo = d.readFloat64()
+	r.Lng.Hi = d.readFloat64()
+	return r
+}
+
+func decodeIndexLoop(d *decoder) *Loop {
+	l := &Loop{}
+	l.vertices = decodeIndexPoints(d)
+	l.originInside = d.readBool()
+	l.depth = readCount(d, maxEncodedLoops, "loop depth")
+	l.bound = decodeIndexRect(d)
+	if d.err != nil {
+		return nil
+	}
+	l.subregionBound = ExpandForSubregions(l.bound)
+	l.index = NewShapeIndex()
+	l.index.Add(l)
+	return l
+}
+
+func decodeIndexPolygon(d *decoder) *Polygon {
+	p := &Polygon{}
+	p.hasHoles = d.readBool()
+	numLoops := readCount(d, maxEncodedLoops, "number of loops")
+	if d.err != nil {
+		return nil
+	}
+	p.loops = make([]*Loop, 0, min(numLoops, decodeAllocChunk))
+	total := 0
+	for range numLoops {
+		l := decodeIndexLoop(d)
+		if d.err != nil {
+			return nil
+		}
+		if total += len(l.vertices); total > maxEncodedVertices {
+			setDecodeErr(d, "too many vertices (%d; max is %d)", total, maxEncodedVertices)
+			return nil
+		}
+		p.loops = append(p.loops, l)
+		p.numVertices += l.NumVertices()
+	}
+	p.bound = decodeIndexRect(d)
+	if d.err != nil {
+		return nil
+	}
+	if numLoops == 0 {
+		p.loops = nil
+	}
+	p.subregionBound = ExpandForSubregions(p.bound)
+	p.initEdgesAndIndex()
+	return p
+}
