+
+package s2
+
+import (
+	"bytes"
+	"encoding/binary"
+	"fmt"
+	"math/rand"
+	"reflect"
+	"testing"
+)
+
+func encodeShapeIndexOrDie(t *testing.T, index *ShapeIndex) []byte {
+	t.Helper()
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatalf("Encode() failed: %v", err)
+	}
+	return buf.Bytes()
+}
+
+func roundTripShapeIndex(t *testing.T, index *ShapeIndex) *ShapeIndex {
+	t.Helper()
+	data := encodeShapeIndexOrDie(t, index)
+	got := &ShapeIndex{}
+	if err := got.Decode(bytes.NewReader(data)); err != nil {
+		t.Fatalf("Decode() failed: %v", err)
+	}
+	return got
+}
+
+// shapeIndexCellsString returns a description of the cell structure of the
+// index, obtained through the public iterator.
+func shapeIndexCellsString(index *ShapeIndex) string {
+	var buf bytes.Buffer
+	for it := index.Iterator(); !it.Done(); it.Next() {
+		fmt.Fprintf(&buf, "%v:", it.CellID())
+		for _, c := range it.IndexCell().shapes {
+			fmt.Fprintf(&buf, " {%d %v %v}", c.shapeID, c.containsCenter, c.edges)
+		}
+		buf.WriteString("\n")
+	}
+	return buf.String()
+}
+
+func checkShapeIndexEqual(t *testing.T, want, got *ShapeIndex) {
+	t.Helper()
+	if got.Len() != want.Len() {
+		t.Fatalf("Len() = %d, want %d", got.Len(), want.Len())
+	}
+	if got.nextID != want.nextID {
+		t.Errorf("nextID = %d, want %d", got.nextID, want.nextID)
+	}
+	if got.maxEdgesPerCell != want.maxEdgesPerCell {
+		t.Errorf("maxEdgesPerCell = %d, want %d", got.maxEdgesPerCell, want.maxEdgesPerCell)
+	}
+	if !got.IsFresh() {
+		t.Errorf("decoded index is not fresh")
+	}
+	for id, ws := range want.shapes {
+		gs := got.Shape(id)
+		if gs == nil {
+			t.Errorf("shape %d missing after decode", id)
+			continue
+		}
+		if reflect.TypeOf(gs) != reflect.TypeOf(ws) {
+			t.Errorf("shape %d type = %T, want %T", id, gs, ws)
+		}
+		if gs.Dimension() != ws.Dimension() || gs.NumEdges() != ws.NumEdges() ||
+			gs.NumChains() != ws.NumChains() || gs.IsEmpty() != ws.IsEmpty() ||
+			gs.IsFull() != ws.IsFull() || gs.ReferencePoint() != ws.ReferencePoint() {
+			t.Errorf("shape %d properties differ after decode", id)
+		}
+		for e := 0; e < ws.NumEdges(); e++ {
+			if gs.Edge(e) != ws.Edge(e) {
+				t.Errorf("shape %d edge %d = %v, want %v", id, e, gs.Edge(e), ws.Edge(e))
+			}
+		}
+		for c := 0; c < ws.NumChains(); c++ {
+			if gs.Chain(c) != ws.Chain(c) {
+				t.Errorf("shape %d chain %d = %v, want %v", id, c, gs.Chain(c), ws.Chain(c))
+			}
+		}
+	}
+	if w, g := shapeIndexCellsString(want), shapeIndexCellsString(got); w != g {
+		t.Errorf("cell structure differs:\ngot:\n%s\nwant:\n%s", g, w)
+	}
+	if !got.IsFresh() {
+		t.Errorf("iterating decoded index triggered a rebuild")
+	}
+}
+
+func allShapeTypesIndex() *ShapeIndex {
+	index := NewShapeIndex()
+	pv := PointVector(parsePoints("0:0 | 1:1 | 2:2"))
+	index.Add(&pv)
+	index.Add(makePolyline("0:0, 2:1, 5:5"))
+	index.Add(makeLoop("0:0, 0:5, 5:5, 5:0"))
+	index.Add(makePolygon("10:10, 10:20, 20:20, 20:10; 12:12, 18:12, 18:18, 12:18", true))
+	index.Add(makeLaxPolyline("-5:-5, -6:-7, -8:-9"))
+	index.Add(LaxLoopFromPoints(parsePoints("30:30, 30:35, 35:35")))
+	index.Add(makeLaxPolygon("40:40, 40:45, 45:45; 41:41, 42:41, 42:42"))
+	index.Add(FullLoop())
+	index.Add(PolygonFromLoops([]*Loop{FullLoop()}))
+	return index
+}
+
+func TestShapeIndexEncodeDecodeAllShapeTypes(t *testing.T) {
+	index := allShapeTypesIndex()
+	index.Build()
+	got := roundTripShapeIndex(t, index)
+	checkShapeIndexEqual(t, index, got)
+
+	// Queries must agree.
+	wantQ := NewContainsPointQuery(index, VertexModelSemiOpen)
+	gotQ := NewContainsPointQuery(got, VertexModelSemiOpen)
+	for i := 0; i < 1000; i++ {
+		p := randomPoint()
+		if i < 4 {
+			p = parsePoint([]string{"2:2", "15:15", "13:13", "31:32"}[i])
+		}
+		w, g := wantQ.ContainingShapes(p), gotQ.ContainingShapes(p)
+		if len(w) != len(g) {
+			t.Fatalf("ContainingShapes(%v) = %d shapes, want %d", p, len(g), len(w))
+		}
+		for j := range w {
+			if got.idForShape(g[j]) != index.idForShape(w[j]) {
+				t.Errorf("ContainingShapes(%v) mismatch", p)
+			}
+		}
+	}
+	if !got.IsFresh() {
+		t.Errorf("querying decoded index triggered a rebuild")
+	}
+}
+
+func TestShapeIndexEncodeDecodeEmpty(t *testing.T) {
